// Throwaway CDP harness for the Alt+A monster. Lives outside the client project.
const PORT = process.env.CDP_PORT || 9222;
const PAGE = 'file:///<home>/source/repos/priv/monster-dev-testruns/2026-08-01-plan-opus/index.html';
const OUT = '<home>/AppData/Local/Temp/claude/<home>-source-repos-priv-monster-dev-testruns-2026-08-01-plan-opus/ddb23ae6-2388-4330-a88c-5c25baf2c7ff/scratchpad/';

const fs = await import('node:fs');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const targets = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
const target = targets.find((t) => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));

let id = 0;
const pending = new Map();
const events = [];
ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
  } else if (msg.method) events.push(msg);
};
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const n = ++id;
    pending.set(n, { resolve, reject });
    ws.send(JSON.stringify({ id: n, method, params }));
  });

const evaluate = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw new Error(expr + ' -> ' + JSON.stringify(r.exceptionDetails.exception));
  return r.result.value;
};
const shot = async (name) => {
  const { data } = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(OUT + name, Buffer.from(data, 'base64'));
};
const altA = async () => {
  for (const type of ['keyDown', 'keyUp']) {
    await send('Input.dispatchKeyEvent', {
      type, modifiers: 1, key: 'a', code: 'KeyA', windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65,
    });
  }
};
const navigate = async () => {
  await send('Page.navigate', { url: PAGE });
  await sleep(900);
};

await send('Page.enable');
await send('Runtime.enable');
await send('Log.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });

const state = () => evaluate(`(() => {
  const m = document.querySelector('.monster');
  const s = document.querySelector('.monster-sprite');
  const r = m.getBoundingClientRect();
  return {
    hidden: m.hidden,
    crossing: m.style.getPropertyValue('--monster-crossing'),
    x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height),
    bgPos: getComputedStyle(s).backgroundPosition,
    bgImg: getComputedStyle(s).backgroundImage.slice(0, 90),
    sheetLoaded: (() => { const i = new Image(); i.src = getComputedStyle(s).backgroundImage.slice(5, -2); return i.complete || 'pending'; })(),
  };
})()`);

const report = {};

// --- 1. normal motion -------------------------------------------------------
await navigate();
report.beforeKey = await state();
report.consoleErrors = events.filter((e) => e.method === 'Log.entryAdded' && e.params.entry.level === 'error')
  .map((e) => e.params.entry.text);

await altA();
await sleep(120);
report.justAfterKey = await state();

await sleep(1500);
report.midWalk1 = await state();
await shot('walk-mid.png');

// second press while walking must be ignored: position keeps advancing, no reset
const xBefore = (await state()).x;
await altA();
await sleep(400);
const after = await state();
report.retrigger = { xBefore, xAfter: after.x, advanced: after.x > xBefore };

// frames actually step
const bgA = (await state()).bgPos;
await sleep(150);
const bgB = (await state()).bgPos;
report.spriteSteps = { bgA, bgB, changed: bgA !== bgB };

