  fs.writeFileSync(OUT + name, Buffer.from(data, 'base64'));
};
const altA = async () => {
  for (const type of ['keyDown', 'keyUp']) {
    await send('Input.dispatchKeyEvent', {
      type, modifiers: 1, key: 'a', code: 'KeyA', windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65,
    });
  }
};
const navigate = async () => {
  await send('Page.navigate', { url: PAGE });
  await sleep(900);
};

await send('Page.enable');
await send('Runtime.enable');
await send('Log.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });

const state = () => evaluate(`(() => {
  const m = document.querySelector('.monster');
  const s = document.querySelector('.monster-sprite');
  const r = m.getBoundingClientRect();
  return {
    hidden: m.hidden,
    crossing: m.style.getPropertyValue('--monster-crossing'),
    x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height),
    bgPos: getComputedStyle(s).backgroundPosition,
    bgImg: getComputedStyle(s).backgroundImage.slice(0, 90),
    sheetLoaded: (() => { const i = new Image(); i.src = getComputedStyle(s).backgroundImage.slice(5, -2); return i.complete || 'pending'; })(),
  };
})()`);

const report = {};

// --- 1. normal motion -------------------------------------------------------
await navigate();
report.beforeKey = await state();
report.consoleErrors = events.filter((e) => e.method === 'Log.entryAdded' && e.params.entry.level === 'error')
  .map((e) => e.params.entry.text);

await altA();
await sleep(120);
report.justAfterKey = await state();

await sleep(1500);
report.midWalk1 = await state();
await shot('walk-mid.png');

// second press while walking must be ignored: position keeps advancing, no reset
const xBefore = (await state()).x;
await altA();
await sleep(400);
const after = await state();
report.retrigger = { xBefore, xAfter: after.x, advanced: after.x > xBefore };

// frames actually step
const bgA = (await state()).bgPos;
await sleep(150);
const bgB = (await state()).bgPos;
report.spriteSteps = { bgA, bgB, changed: bgA !== bgB };

// walk finishes and cleans up
let waited = 0;
while (!(await evaluate(`document.querySelector('.monster').hidden`)) && waited < 20000) {
  await sleep(250); waited += 250;
}
report.finished = { hiddenAgain: await evaluate(`document.querySelector('.monster').hidden`), afterMs: waited + 2020 };

// re-fires cleanly a second time
await altA();
await sleep(600);
report.secondRun = await state();
await evaluate(`document.querySelector('.monster').hidden = true`);

// --- 2. reduced motion ------------------------------------------------------
await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-motion', value: 'reduce' }] });
await navigate();
await altA();
await sleep(400);
report.reducedVisible = await state();
await shot('reduced.png');
await sleep(4200);
report.reducedHiddenAfter = await evaluate(`document.querySelector('.monster').hidden`);
await send('Emulation.setEmulatedMedia', { features: [] });

// --- 3. narrow window: duration must scale, not the tempo -------------------
await send('Emulation.setDeviceMetricsOverride', { width: 480, height: 720, deviceScaleFactor: 1, mobile: false });
await navigate();
await altA();
await sleep(150);
report.narrowCrossing = (await state()).crossing;

// --- 4. the site's own behaviour still works --------------------------------
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 720, deviceScaleFactor: 1, mobile: false });
await navigate();
report.smoothScrollIntact = await evaluate(`(() => {
  document.querySelector('nav a[href="#about"]').click();
  return new Promise((r) => setTimeout(() => r(window.scrollY > 0), 800));
})()`);
report.lateConsoleErrors = events.filter((e) => e.method === 'Log.entryAdded' && e.params.entry.level === 'error')
  .map((e) => e.params.entry.text);

console.log(JSON.stringify(report, null, 2));
ws.close();

